package com.codepilot1c.core.edt.development;
import static org.junit.Assert.*;
import org.junit.Test;
import java.util.*;
import java.nio.file.*;
public class ChangeCheckServiceTest {
    static class Backend implements ChangeCheckService.Backend {
        List<Map<String,Object>> diagnostics=new ArrayList<>();boolean busy=false;
        public Map<String,Object> capture(String p,List<String> f){return new LinkedHashMap<>(Map.of("project",p,"project_location","fixture","diagnostics",new ArrayList<>(diagnostics),"files",List.of(Map.of("path","src/CommonModules/Fixture/Module.bsl","object","CommonModules/Fixture","sha256","hash")),"builders_busy",busy,"git_state","explicit_files","branch",""));}
        public Map<String,Object> run(String id){return Map.of("run_id",id,"project",id.equals("wrong")?"Other":"Fixture","phase","completed","terminal",true,"event_cursor",0);}
    }
    @Test public void baselineDeltaSurvivesJsonNumericConversion()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend b=new Backend();b.diagnostics.add(Map.of("path","a.bsl","line",1,"severity",2,"message","old"));var service=new ChangeCheckService(f.path,b);String id=(String)service.baseline("Fixture",null).get("baseline_id");assertEquals(0L,service.changes("Fixture",null,id,null).get("new_errors"));b.diagnostics.add(Map.of("path","a.bsl","line",2,"severity",2,"message","new"));var result=service.changes("Fixture",null,id,null);assertEquals(1L,result.get("new_errors"));assertEquals(2L,result.get("errors"));}}
    @Test public void absentBaselineDoesNotInventNewErrorsOrRuntimeSuccess()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){var service=new ChangeCheckService(f.path,new Backend());var result=service.changes("Fixture",null,null,null);assertEquals("unknown_without_baseline",result.get("new_errors"));assertEquals(false,result.get("runtime_verified"));assertEquals(false,result.get("writes_database"));}}
    @Test public void busyBuilderAndWrongRunAreExplicit()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend b=new Backend();b.busy=true;var service=new ChangeCheckService(f.path,b);assertEquals("builders_running",service.changes("Fixture",null,null,null).get("static_verdict"));assertThrows(IllegalArgumentException.class,()->service.changes("Fixture",null,null,"wrong"));}}
    @Test public void detailsArePagedAndProjectBound()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend b=new Backend();for(int i=0;i<7;i++)b.diagnostics.add(Map.of("path","f","line",i,"severity",2,"message","e"));var service=new ChangeCheckService(f.path,b);var result=service.changes("Fixture",null,null,null);String id=(String)result.get("check_id");assertEquals(true,service.details("Fixture",id,"diagnostics",0,2).get("has_more"));assertEquals(2,((List<?>)service.details("Fixture",id,"diagnostics",0,2).get("items")).size());assertThrows(IllegalArgumentException.class,()->service.details("Other",id,"diagnostics",0,2));assertThrows(IllegalArgumentException.class,()->service.details("Fixture",id,"arbitrary",0,2));}}
    @Test public void identicalPollsReuseSnapshotAndBoundLargeFileReads()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend backend=new Backend();var service=new ChangeCheckService(f.path,backend);String a=(String)service.changes("Fixture",null,null,null).get("check_id"),c=(String)service.changes("Fixture",null,null,null).get("check_id");assertEquals(a,c);Path root=f.path.toRealPath();Files.writeString(root.resolve("small.txt"),"small");try(var sparse=new java.io.RandomAccessFile(root.resolve("large.bin").toFile(),"rw")){sparse.setLength(9L*1024*1024);}var rows=ChangeCheckService.inspectFiles(root,List.of("small.txt","large.bin"));assertEquals("hashed",rows.get(0).get("hash_state"));assertEquals("omitted_size_limit",rows.get(1).get("hash_state"));assertEquals("omitted",rows.get(1).get("sha256"));assertThrows(IllegalArgumentException.class,()->ChangeCheckService.inspectFiles(root,List.of("../escape")));}}
    @Test public void omittedHashNeverLooksLikeZeroChanges()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend backend=new Backend(){@Override public Map<String,Object> capture(String p,List<String> files){var map=super.capture(p,files);map.put("files",List.of(Map.of("path","large.bin","sha256","omitted","hash_state","omitted_size_limit")));return map;}};var service=new ChangeCheckService(f.path,backend);String id=(String)service.baseline("Fixture",null).get("baseline_id");var result=service.changes("Fixture",null,id,null);assertEquals("unknown_incomplete_comparison",result.get("changed_files"));assertEquals(1L,result.get("unknown_file_changes"));assertEquals(false,result.get("file_comparison_complete"));}}
    @Test public void explicitFileOutsideBaselineIsUnknownNotNew()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend backend=new Backend(){@Override public Map<String,Object> capture(String p,List<String> files){var map=super.capture(p,files);map.put("files",List.of(Map.of("path",files.get(0),"sha256","same")));return map;}};var service=new ChangeCheckService(f.path,backend);String id=(String)service.baseline("Fixture",List.of("A")).get("baseline_id");var result=service.changes("Fixture",List.of("B"),id,null);assertEquals("unknown_incomplete_comparison",result.get("changed_files"));assertEquals(0L,result.get("known_changed_files"));assertEquals(1L,result.get("unknown_file_changes"));}}
    @Test public void scenarioSourceMatchIsExplicitAndChangesInvalidateIt()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){
        class ReceiptBackend extends Backend {
            String hash="old";final Map<String,Object> receipt=Map.of("complete",true,"sha256","old","project_location","fixture");
            public Map<String,Object> run(String id){var r=new HashMap<>(super.run(id));r.put("source_receipts",Map.of("before",receipt,"launch",receipt,"finished",receipt));return r;}
            public Map<String,Object> sourceReceipt(String p){return Map.of("complete",true,"sha256",hash,"project_location","fixture");}
        }
        var backend=new ReceiptBackend();var service=new ChangeCheckService(f.path,backend);assertEquals("matched_at_checkpoints",service.changes("Fixture",null,null,"own").get("scenario_sources_match"));backend.hash="edited";assertEquals("changed",service.changes("Fixture",null,null,"own").get("scenario_sources_match"));
    }}
}
